with base as (select id, store_name, city, region, opened_date, trim(city) as clean_city, coalesce(region, 'UNKNOWN') as region_filled from stores where opened_date >= date '2023-09-06' and region is not null and city in ('Bangkok', 'Tokyo')) select * from (select *, row_number() over (partition by city order by opened_date desc, id) as rank_in_group from base) x where rank_in_group = 1;
